<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class NotificationController extends Controller{public function index(Request $r){$q=DB::table('user_notifications')->where('user_id',$r->user()->id);return ['unread'=>(clone $q)->whereNull('read_at')->count(),'notifications'=>$q->latest()->paginate(20)];}public function read(Request $r,int $notification){abort_unless(DB::table('user_notifications')->where('id',$notification)->where('user_id',$r->user()->id)->update(['read_at'=>now(),'updated_at'=>now()]),404);return response()->noContent();}public function readAll(Request $r){DB::table('user_notifications')->where('user_id',$r->user()->id)->whereNull('read_at')->update(['read_at'=>now(),'updated_at'=>now()]);return response()->noContent();}}
